fn('home', '''function home(){close();const t=themed(),pendingSession=pending(),stats=D.counts.byTheme[theme],ids=theme==='lol'?['lol-uzi','lol-xiaohu','lol-dasima']:theme==='basket'?['basket-kobe','basket-lebron','basket-curry']:['abstract-shake-director','abstract-liziqi','abstract-fengge'],samples=theme==='lol'?['collector-union','gold-rain','s8-rewrite']:theme==='basket'?['mamba-clock','kneel','goodnight-three']:['auto-dance','no-precut','slow-craft'],headline=theme==='lol'?'世界上另一个我，<br>这把必须<em>整整齐齐。</em>':theme==='basket'?'金闪闪队，<br>谁是你的<em>平行首发？</em>':'前奏一响，<br>另一个我<em>自动上线。</em>',topics=theme==='lol'?['S赛与冠军','经典热梗','对线小技巧','大乱斗脑洞']:theme==='basket'?['老大加练','勒邦詹氏','裤衩子三分','现役与经典']:['舞蹈二创','翻唱开麦','峰哥日常','自媒体热梗'];render(`<section class="home v7-home v9-home"><div class="edition"><span><i></i> 世界上另一个我 · 三个梗宇宙</span><span>VOL.09</span></div><div class="theme-picker" role="group" aria-label="三个主题板块">${D.themes.map((a,i)=>`<button data-action="theme" data-theme="${a.id}" aria-pressed="${theme===a.id}" style="--theme-color:${a.accent}"><span>${a.icon}</span><strong>${a.id==='basket'?'金闪闪队 · NBA':a.name}</strong><small>${['S赛 / 对线 / 大乱斗','现役 / 经典球星梗','跳舞 / 翻唱 / 自媒体'][i]}</small></button>`).join('')}</div><div class="topic-chips">${topics.map(x=>`<span>${x}</span>`).join('')}</div><section class="launch-grid"><div class="launch-copy"><span class="eyebrow">ANOTHER ME / THREE WORLDS, ONE YOU.</span><h1>${headline}</h1><p>${theme==='lol'?'队友四把收集者，第五把必须有我。<br>S赛、对线、大乱斗都在同一局里接梗。':theme==='basket'?'老大的闹钟，勒邦詹氏的膝盖，<br>裤衩子的射程——看看谁在另一个宇宙等你。':'摇一摇、翻唱、活人感与旅行日常，<br>这次的专属人物，由你的反应决定。'}</p><div class="mode-picker" role="group" aria-label="选择题量">${D.modes.map((n,i)=>`<button data-action="mode" data-count="${n}" aria-pressed="${count===n}"><b>${n}<small>题</small></b><strong>${['先玩一口','认真接梗','整活全开'][i]}</strong><span>${theme==='lol'?n/4+' 个连续小剧场':'随机日常与名场面'}</span></button>`).join('')}</div><button class="primary start" data-action="start">查收我的平行身份 <span>↗</span></button><p class="micro launch-note">选一个答案，自动下一题 · 可返回改选</p>${pendingSession?`<button class="resume-compact" data-action="resume">上局已答 ${pendingSession.answers.filter(a=>a!==null).length}/${pendingSession.count} 题，接着玩 →</button>`:''}</div><div class="launch-art" aria-label="你的平行身份候选"><span class="art-topline">人物 × 专属海克斯 / 等你的第一反应</span>${ids.map((id,i)=>`<div class="face-ticket face-${i}">${portrait(person(id))}<span>${esc(person(id).nickname||person(id).name)}</span></div>`).join('')}<span class="art-stamp">人物联动<br>本局限定</span></div></section><div class="launch-links"><button class="text" data-action="story-preview">先看一段我的平行人生 ↗</button><button class="text" data-action="gallery">全部 ${stats.people} 位人物 ↗</button></div>${theme==='lol'?`<section class="sample-case"><div class="sample-real-icons">${perkIcon(findCard('collector-union'))}</div><div><span class="eyebrow">先试一道 / 不计入正式结果</span><h2>队友四个出了收集者，你怎么办？</h2></div><div class="case-choices">${[['挂机','afk'],['开送','int'],['必须出收集者','collector'],['给队友挡伤害','protect']].map(([label,b])=>`<button data-action="sample" data-behavior="${b}">${label}<span>↗</span></button>`).join('')}</div></section>`:theme==='abstract'?`<section class="editorial-note"><span>本期热梗 / ${esc(D.editorial.checkedAt)}</span><p>跳舞、翻唱与自媒体日常，穿插经典梗回归。</p><button class="text" data-action="trend-note">看看梗出处与本期整理说明 ↗</button></section>`:''}<div class="section-head"><h2>人物有梗，海克斯也有专属。</h2><button class="text" data-action="card-gallery">全部 ${stats.cards} 张 ↗</button></div><div class="perk-peeks">${samples.map(id=>{const a=findCard(id);return `<button class="perk-peek ${a.rarity}" data-action="peek" data-id="${id}">${perkIcon(a)}<strong>${esc(a.name)}</strong><small>${(a.signatureFor||[]).map(id=>D.characters.find(c=>c.theme===theme&&c.personId===id)?.nickname||D.characters.find(c=>c.theme===theme&&c.personId===id)?.name||'').filter(Boolean).slice(0,2).map(esc).join(' / ')||'本轮反应匹配'}</small></button>`;}).join('')}</div>${theme==='lol'?memeScenes():''}<div class="pool-strip"><strong>${stats.questions}<small>道本主题情境</small></strong><strong>${stats.people}<small>位候选人物</small></strong><strong>${stats.cards}<small>张主题海克斯</small></strong></div><p class="tiny">本作自制恶搞海克斯与架空剧情，依据真实作答匹配；新开一局重新抽题。</p></section>`);}''')
fn('start', '''function start(chapter=null,sourceSeries=null){close();series='all';const k='first.'+theme;session=E.draw(D,theme,count,read(k),undefined,'all');if(chapter){theme='lol';session=E.draw(D,theme,count,read('first.lol'),undefined,'all');const chosen=D.questions.filter(q=>q.theme==='lol'&&q.chapter===chapter&&(!sourceSeries||q.series===sourceSeries)).sort((a,b)=>a.stage-b.stage);if(chosen.length===4){const ids=new Set(chosen.map(q=>q.id));session.deck=[...chosen.map(q=>({id:q.id,order:E.shuffle(q.options.map(o=>o.id))})),...session.deck.filter(d=>!ids.has(d.id))].slice(0,count);}}write('first.'+theme,session.deck[0].id);write('theme',theme);write('count',count);save();quiz();}''')
