fn('quiz', '''function quiz(){const q=E.questionAt(session,D),entry=session.deck[session.index],done=session.answers.filter(a=>a!==null).length,c=E.context(session,D),stage=['开场','接梗','临场','收尾'];render(`<section class="quiz narrow"><div class="quiz-meta"><span>${seriesName()} / ${q.chapterName?esc(q.chapterName):esc(q.scene)}</span><strong>${String(session.index+1).padStart(2,'0')} <small>/ ${session.count}</small></strong></div><progress value="${done}" max="${session.count}" aria-label="已完成${done}道题"></progress>${q.theme==='lol'?`<div class="chapter-track" aria-label="同一剧场的四幕">${stage.map((s,i)=>`<span class="${i===q.stage?'active':i<q.stage?'done':''}">${i+1} ${s}</span>`).join('')}</div>`:''}<div class="question"><span class="question-scene">${esc(q.scene)} / 按第一反应接梗</span>${c?`<div class="previous-choice"><small>上一幕，你选了</small><p>「${esc(c.previousChoice)}」</p></div>`:''}${questionArt(q)}<h1>${esc(q.title)}</h1>${q.tip?`<p class="plain-tip">梗外小知识：${esc(q.tip)}</p>`:''}<div class="options">${entry.order.map((id,i)=>{const o=q.options.find(o=>o.id===id);return `<button class="option" data-action="answer" data-question="${q.id}" data-id="${id}" aria-pressed="${session.answers[session.index]===id}"><i>${'ABCD'[i]}</i><span>${esc(o.text)}</span></button>`;}).join('')}</div><p class="auto-status" id="answer-status" role="status" aria-live="polite">点选后自动下一题，选错可返回修改。</p><div class="quiz-nav"><button class="text" data-action="previous">${session.index?'← 返回上一题改选':'← 返回首页'}</button><small>${session.index===session.count-1?'选完即揭晓平行身份':'不需要再点“下一题”'}</small></div></div><p class="micro save-note">已答 ${done} / ${session.count} · 本轮题目与选项已保存在本机</p></section>`);}''')
